with products_by_supplier as (select supplier_id, sum(case when brand = 'Stark' then 1 else 0 end) as stark_count from products group by supplier_id) select suppliers.id, suppliers.country, suppliers.rating, products_by_supplier.stark_count from suppliers inner join products_by_supplier on suppliers.id = products_by_supplier.supplier_id where products_by_supplier.stark_count >= 71 order by suppliers.rating, id desc;
